wire [7:0] next_major={1'b0,major}+8'd1;
wire [14:0] triangle_product=major*next_major;
wire [12:0] packed_address=triangle_product[13:1]+{6'd0,minor};
reg [1:0] bank; reg swapped_d,valid_d;
